461	/**
462	 * 主动发起与对端的 WebSocket 连接。
463	 * 流程: 连接 ws://peer_ip:ws_port/ws/chat → 发 connect_request → 等 connect_accepted
464	 */
465	async function connectToPeer(uuid, name, ip) {
466	    // 如果已有活跃连接，直接打开聊天
467	    if (activeChats.has(uuid)) {
468	        openChat(uuid);
469	        return;
470	    }
471	
472	    // 获取对端 ws_port（从在线节点列表）
473	    const peer = onlinePeers.get(uuid);
474	    if (!peer) {
475	        showToast('对方不在线');
476	        return;
477	    }
478	
479	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
480	
481	    try {
482	        const peerPort = peer.ws_port || 50002;
483	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
484	        const ws = new WebSocket(wsUrl);
485	
486	        ws.onopen = () => {
487	            // 发送连接请求
488	            ws.send(JSON.stringify({
489	                type: 'connect_request',
490	                uuid: myInfo.uuid,
491	                name: myInfo.name,
492	                token: '',  // Token 由后端在 UDP 层面处理
493	            }));
494	        };
495	
496	        ws.onmessage = (e) => {
497	            const msg = JSON.parse(e.data);
498	            if (msg.type === 'connect_accepted') {
499	                activeChats.set(uuid, ws);
500	                setupPeerMessageHandler(uuid, ws);
501	                addSystemMessage(uuid, '连接已建立');
502	            } else if (msg.type === 'connect_rejected') {
503	                ws.close();
504	                addSystemMessage(uuid, '对方拒绝了连接请求');
505	                showToast('对方拒绝了连接请求');
506	            }
507	        };
508	
509	        ws.onclose = () => {
510	            activeChats.delete(uuid);
511	            addSystemMessage(uuid, '连接已断开');
512	            updateChatHeaderStatus();
513	        };
514	
515	        ws.onerror = () => {
516	            activeChats.delete(uuid);
517	            addSystemMessage(uuid, '连接失败，请稍后重试');
518	            showToast('连接失败');
519	            ws.close();
520	        };
521	
522	    } catch (e) {
523	        addSystemMessage(uuid, `连接失败: ${e.message}`);
524	    }
525	}
