527	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
528	function setupPeerMessageHandler(uuid, ws) {
529	    ws.onmessage = (e) => {
530	        const msg = JSON.parse(e.data);
531	        if (msg.type === 'chat') {
532	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
533	            handleDirectChatMessage(uuid, msg);
534	        } else if (msg.type === 'file_response') {
535	            handleFileRequestResponse(msg);
536	        } else if (msg.type === 'file_cancel') {
537	            handleTransferCancelled(msg);
538	        } else if (msg.type === 'ack') {
539	            handleMessageAck(msg);
540	        }
541	    };
542	}
