676	async function sendFile(uuid, file) {
677	    const CHUNK_SIZE = 64 * 1024; // 64KB
678	    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
679	    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
680	
681	    // 通过聊天 WS 发 file_request
682	    const ws = activeChats.get(uuid);
683	    if (!ws) {
684	        showToast('未连接到对方，请先建立聊天');
685	        return;
686	    }
687	
688	    ws.send(JSON.stringify({
689	        type: 'file_request',
690	        transfer_id: transferId,
691	        file_name: file.name,
692	        file_size: file.size,
693	        chunk_size: CHUNK_SIZE,
694	        total_chunks: totalChunks,
695	        resume: false,
696	    }));
697	
698	    // 等待 file_response（通过 control ws 回调继续）
699	    addSystemMessage(uuid, `发送文件: ${file.name} (${formatSize(file.size)})`);
700	
701	    // 开始发送分片
702	    window._pendingFileTransfers = window._pendingFileTransfers || {};
703	    window._pendingFileTransfers[transferId] = { file, uuid, totalChunks, CHUNK_SIZE, transferId, currentChunk: 0 };
704	
705	    // 等待对方响应后开始发送分片
706	    const originalHandler = handleFileRequestResponse;
707	    const onceHandler = (msg) => {
708	        if (msg.transfer_id === transferId) {
709	            if (msg.accepted) {
710	                startChunkUpload(transferId);
711	            }
712	            // 恢复原始处理器
713	            window._fileResponseHandler = originalHandler;
714	        }
715	    };
716	    window._fileResponseHandler = (msg) => {
717	        originalHandler(msg);
718	        onceHandler(msg);
719	    };
720	}
721	
722	function handleFileRequestResponse(msg) {
723	    if (window._fileResponseHandler) {
724	        window._fileResponseHandler(msg);
725	    } else if (msg.accepted) {
726	        // 查找匹配的传输并开始上传
727	        const transfers = window._pendingFileTransfers || {};
728	        for (const [tid, t] of Object.entries(transfers)) {
729	            if (!t.started) {
730	                t.started = true;
731	                startChunkUpload(tid);
732	                break;
733	            }
734	        }
735	    }
736	}
737	
738	async function startChunkUpload(transferId) {
739	    const t = window._pendingFileTransfers?.[transferId];
740	    if (!t) return;
741	
742	    const peer = onlinePeers.get(t.uuid);
743	    if (!peer) {
744	        showToast('对方不在线，无法发送文件');
745	        return;
746	    }
747	
748	    const file = t.file;
749	    const CHUNK_SIZE = t.CHUNK_SIZE;
750	    const totalChunks = t.totalChunks;
751	
752	    for (let i = t.currentChunk; i < totalChunks; i++) {
753	        const start = i * CHUNK_SIZE;
754	        const end = Math.min(start + CHUNK_SIZE, file.size);
755	        const blob = file.slice(start, end);
756	        const dataB64 = await readAsBase64(blob);
757	
758	        let retries = 0;
759	        let success = false;
760	
761	        while (retries < 3 && !success) {
762	            try {
763	                const peerPort = peer.ws_port || 50002;
764	            const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
765	                    method: 'POST',
766	                    headers: { 'Content-Type': 'application/json' },
767	                    body: JSON.stringify({
768	                        transfer_id: transferId,
769	                        chunk_index: i,
770	                        data: dataB64,
771	                    }),
772	                });
773	                if (resp.ok) {
774	                    success = true;
775	                    t.currentChunk = i + 1;
776	                } else {
777	                    retries++;
778	                }
779	            } catch (e) {
780	                retries++;
781	            }
782	        }
783	
784	        if (!success) {
785	            addSystemMessage(t.uuid, '文件传输中断，等待对方重新上线');
786	            return; // 传输暂停，等待后续续传
787	        }
788	    }
789	
790	    // 完成
791	    try {
792	        const peerPort = peer.ws_port || 50002;
793	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
794	            method: 'POST',
795	            headers: { 'Content-Type': 'application/json' },
796	            body: JSON.stringify({ transfer_id: transferId }),
797	        });
798	        addSystemMessage(t.uuid, `文件 ${file.name} 发送完成 ✓`);
799	    } catch (e) {
800	        addSystemMessage(t.uuid, '文件传输完成确认失败');
801	    }
802	
803	    delete window._pendingFileTransfers?.[transferId];
804	}
805	
806	function readAsBase64(blob) {
807	    return new Promise((resolve) => {
808	        const reader = new FileReader();
809	        reader.onloadend = () => {
810	            const result = reader.result;
811	            // 去掉 "data:...;base64," 前缀
812	            const b64 = result.split(',')[1] || result;
813	            resolve(b64);
814	        };
815	        reader.readAsDataURL(blob);
816	    });
817	}
818	
819	// ===== 文件传输弹窗 =====
