821	    fileModalTitle.textContent = '文件传输请求';
822	    fileModalBody.innerHTML = `
823	        <p><strong>${esc(msg.from_name)}</strong> 想发送文件:</p>
824	        <p>📄 ${esc(msg.file_name)} (${formatSize(msg.file_size)})</p>`;
825	    fileModalButtons.innerHTML = `
826	        <button id="btn-file-accept" class="btn-primary">接收</button>
827	        <button id="btn-file-reject">拒绝</button>`;
828	    fileModalOverlay.style.display = '';
829	
830	    $('btn-file-accept').addEventListener('click', () => {
831	        controlWs.send(JSON.stringify({
832	            type: 'file_response',
833	            transfer_id: msg.transfer_id,
834	            accepted: true,
835	        }));
836	        fileModalOverlay.style.display = 'none';
837	    });
838	    $('btn-file-reject').addEventListener('click', () => {
839	        controlWs.send(JSON.stringify({
840	            type: 'file_response',
841	            transfer_id: msg.transfer_id,
842	            accepted: false,
843	        }));
844	        fileModalOverlay.style.display = 'none';
845	    });
846	}
