890	    // 简单的 toast 提示
891	    const div = document.createElement('div');
892	    div.style.cssText = 'position:fixed;top:60px;right:20px;background:#333;color:#fff;padding:10px 20px;border-radius:6px;z-index:200;font-size:13px;animation:fadeOut 2s forwards';
