function sendCurrentMessage() {
    const content = msgInput.value.trim();
    if (!content || !currentChat) return;
    msgInput.value = '';

    const msgId = generateMsgId();
    const contact = contacts.get(currentChat);

    // 保存到本地联系人消息列表
    if (!contact.messages) contact.messages = [];
    contact.messages.push({
        from: 'me',
        content: content,
        msg_id: msgId,
        timestamp: new Date().toISOString(),
        status: 'sending',
    });
    renderMessages(currentChat);

    // 优先通过 chat WS 直接发给对方后端（A→B后端的 /ws/chat）
    // 对方后端 _relay_from_peer 收到后：保存消息 → 转发给对方的浏览器 → 回复 ACK
    const chatWs = activeChats.get(currentChat);
    if (chatWs && chatWs.readyState === WebSocket.OPEN) {
        pendingMessages.set(msgId, { content, uuid: currentChat, status: 'sending' });
        chatWs.send(JSON.stringify({
            type: 'chat',
            msg_id: msgId,
            content: content,
        }));
    } else {
        // fallback：没有活跃 chat WS 时标记失败
        contact.messages[contact.messages.length - 1].status = 'failed';
        renderMessages(currentChat);
        showToast('未连接到对方，请先建立连接');
        return;
    }

    // 5秒超时：没收到 ACK 则标记失败
    setTimeout(() => {
        const pending = pendingMessages.get(msgId);
        if (pending && pending.status === 'sending') {
            pending.status = 'failed';
            pendingMessages.set(msgId, pending);
            if (currentChat) renderMessages(currentChat);
        }
    }, 5000);
}

